import json,subprocess
from pathlib import Path
sql='''WITH sold AS(SELECT o.id order_id,o.company_id,l.product_id,sum(l.qty) qty FROM pos_order o JOIN pos_order_line l ON l.order_id=o.id JOIN product_product pp ON pp.id=l.product_id JOIN product_template pt ON pt.id=pp.product_tmpl_id WHERE o.state IN ('paid','done','invoiced') AND pt.is_storable GROUP BY 1,2,3), delivered AS(SELECT p.pos_order_id order_id,ml.product_id,sum(CASE WHEN dst.usage='customer' THEN ml.quantity_product_uom ELSE -ml.quantity_product_uom END) qty FROM stock_move_line ml JOIN stock_move m ON m.id=ml.move_id JOIN stock_picking p ON p.id=m.picking_id JOIN stock_location src ON src.id=ml.location_id JOIN stock_location dst ON dst.id=ml.location_dest_id WHERE m.state='done' AND p.pos_order_id IS NOT NULL AND ((src.usage='internal' AND dst.usage='customer') OR (src.usage='customer' AND dst.usage='internal')) GROUP BY 1,2), compared AS(SELECT s.*,coalesce(d.qty,0) delivered FROM sold s LEFT JOIN delivered d USING(order_id,product_id)) SELECT company_id,count(*) order_products,sum(qty) sold,sum(delivered) delivered,count(*) FILTER(WHERE abs(qty-delivered)>.001) differences,sum(qty-delivered) difference FROM compared GROUP BY company_id ORDER BY 1'''
r=subprocess.run(['docker','exec','odoo-postgres18-1','psql','-U','odoo','-d','prod','-Atc',"select json_agg(t) from ("+sql+") t"],capture_output=True,text=True,check=True)
Path('/tmp/advisor-stock-audit/pos-reconciliation.json').write_text(r.stdout)
print(r.stdout)
